<?php require 'header.php'; admin_require_permission('delete'); $db=db_load(); $id=get('id'); $db['patients']=array_values(array_filter($db['patients'],fn($p)=>$p['id']!==$id)); $db['appointments']=array_values(array_filter($db['appointments'],fn($a)=>$a['patient_id']!==$id)); db_save($db); redirect('patients.php');
